struct ORdmmLand{T <: AbstractVector} <: AbstractCardiacCellModel
    parameters::T
end

ORdmmLand() = ORdmmLand(Float64)

function ORdmmLand(::Type{ElT}) where {ElT <: Number}
    p = zeros(ElT, 139)
    init_parameter_values!(p)
    return ORdmmLand(p)
end

function ORdmmLand(::Type{VT}) where {VT <: AbstractVector}
    p = zeros(eltype(VT), 139)
    init_parameter_values!(p)
    return ORdmmLand(VT(p))
end


