const ORDMMLAND_STATE_INDEX = Dict{Symbol, Int}(
    n => i for (i, n) in enumerate(ORDMMLAND_STATE_NAMES)
)
const ORDMMLAND_PARAMETER_INDEX = Dict{Symbol, Int}(
    n => i for (i, n) in enumerate(ORDMMLAND_PARAMETER_NAMES)
)

state_index(::ORdmmLand, name::Symbol) = ORDMMLAND_STATE_INDEX[name]
parameter_index(::ORdmmLand, name::Symbol) = ORDMMLAND_PARAMETER_INDEX[name]
state_names(::ORdmmLand) = ORDMMLAND_STATE_NAMES
parameter_names(::ORdmmLand) = ORDMMLAND_PARAMETER_NAMES


num_states(::ORdmmLand) = NUM_STATES
num_parameters(::ORdmmLand) = NUM_PARAMS
transmembrane_potential_index(::ORdmmLand) = 48

function default_initial_state(model::ORdmmLand{T}) where {T}
    u = zeros(eltype(T), NUM_STATES)
    init_state_values!(u)
    return u
end

function (model::ORdmmLand)(du, u, ::Nothing, t)
    rhs(t, u, model.parameters, du, nothing, nothing)
    return nothing
end

function (model::ORdmmLand)(du, u, p::SpatialContext, t)
    rhs(t, u, model.parameters, du, p.x, p.overrides)
    return nothing
end

num_monitors(::ORdmmLand) = 309
monitor_names(::ORdmmLand) = ORDMMLAND_MONITOR_NAMES

function monitor_values!(mon, u, t, model::ORdmmLand)
    # Six arguments: monitor_values inherits the two spatial arguments
    # from _rhs_arguments, exactly as rhs does. Monitors are not
    # spatially overridden, so both are nothing.
    monitor_values(t, u, model.parameters, mon, nothing, nothing)
    return nothing
end
